#include <iostream>
#include <vector>
#include <algorithm>
#include <cstring>
#include <cstdio>
#include <cmath>
#include <cstdlib>
#include <ctime>
#include <queue>
#include <set>
#include <map>
#include <stack>
using namespace std;

typedef long long LL;
const int N=250100;

int readInt() {
    int result=0; bool positive=true; char c=getchar();
    while ((c<'0'||c>'9') && c!='-') c=getchar();
    if (c=='-') { positive=false; c=getchar(); }
    while (c>='0' && c<='9') { result=result*10+c-'0'; c=getchar(); }
    return positive ? result : -result;
}

int mod,m;
int sizeArr[N],invArr[N];
struct DataTransform { int a[19]; }f[N];

inline int fastPow(int base, int exp) {
    int res=1;
    while (exp) {
        if (exp & 1) res=1LL*res*base%mod;
        base=1LL*base*base%mod; exp>>=1;
    }
    return res;
}

int main() {
#ifndef ONLINE_JUDGE
    freopen("CF838C.in","r",stdin);
    freopen("CF838C.out","w",stdout);
#endif
    int i, s, n=readInt(), k=readInt(), a, b, y, t[20]={}, p[20]={};
    DataTransform *F, *G;
    mod=readInt();

    if (n&1) {
        printf("%d\n", fastPow(k, n));
        return 0;
    }

    for (i=0; i<18; i++) m+= (n>>i)&1;

    for (i=0, s=1; i<=n; i++) {
        invArr[i]=i<2 ? 1 : -1LL*(mod/i)*invArr[mod%i]%mod;
        sizeArr[i]=sizeArr[i>>1]+(i&1);
        s=1LL*s*invArr[i]%mod;
        if ((i&n)==i)
            f[i].a[sizeArr[i]]=s;
    }

    for (i=0; i<18; i++)
        if (n>>i&1)
            for (s=n; s; (--s)&=n)
                if (s>>i&1)
                    for (a=0, F=&f[s^(1<<i)], G=&f[s]; a<=m; a++) (G->a[a]+=F->a[a])%=mod;

    for (i=0; i<=n; i++) if ((i&n)==i) {
        F=&f[i];
        for (a=0; a<=m; a++) t[a]=F->a[a], F->a[a]=!a;
        for (y=k; y; y>>=1) {
            if (y&1) {
                for (a=0; a<=m; a++) p[a]=F->a[a], F->a[a]=0;
                for (a=0; a<=m; a++)
                    if (t[a])
                        for (b=0; a+b<=m; b++)
                            F->a[a+b]=(F->a[a+b]+1LL*t[a]*p[b])%mod;
            }
            if (y>>=1) {
                for (a=0; a<=m; a++) p[a]=t[a], t[a]=0;
                for (a=0; a<=m; a++)
                    if (p[a])
                        for (b=0; a+b<=m; b++)
                            t[a+b]=(t[a+b]+1LL*p[a]*p[b])%mod;
            }
        }
    }

    for (i=0; i<18; i++)
        if (n>>i&1)
            for (s=n; s; (--s)&=n)
                if (s>>i&1)
                    for (a=0, F=&f[s^(1<<i)], G=&f[s]; a<=m; a++) (G->a[a]-=F->a[a])%=mod;

    s=f[n].a[m];
    for (i=n; i; i--) s=1LL*s*i%mod;
    printf("%d\n", ((fastPow(k, n)-s)%mod+mod)%mod);
    return 0;
}
